/** Optional integration: calls the installed compass's own bounded search worker, never /locate on tick. */
@Mod.EventBusSubscriber(modid=Dynasty.MODID)
public final class DynastyCompassBridge {
    public record Destination(String id,String label,String dimension,String target,boolean biome) {}
    public static final List<Destination> DESTINATIONS=List.of(
        new Destination("yunqi_manor","云栖庄园","minecraft:overworld","yunqi_manor",false),
        new Destination("longque_sanctuary","龙阙镇渊巨像","minecraft:overworld","longque_sanctuary",false),
        new Destination("tiangong_citadel","天工山城","minecraft:overworld","tiangong_citadel",false),
        new Destination("tiangong_mining_estate","山麓采矿庄园","minecraft:overworld","tiangong_mining_estate",false),
        new Destination("chensha_xuangong","沉沙玄宫","minecraft:overworld","chensha_xuangong",false),
        new Destination("palace","皇家宫殿","celestial_dynasty","palace",false),
        new Destination("academy","国子监","celestial_dynasty","academy",false),
        new Destination("imperial_tomb","帝陵建筑（不保证刷始皇）","celestial_dynasty","imperial_tomb",false),
        new Destination("great_wall_gate","长城关隘","celestial_dynasty","great_wall_gate",false),
        new Destination("star_altar","九霄星坛","jiuxiao","star_altar",false),
        new Destination("star_vault","九霄观星密室（星盘机关）","jiuxiao","star_vault",false),
        new Destination("music_ruin","古乐遗址（编钟机关）","minecraft:overworld","music_ruin",false),
        new Destination("seal_vault","幽冥四象封印室（灯阵机关）","underworld","seal_vault",false),
        new Destination("yinsi_wangsi_cheng","阴司枉死城","underworld","yinsi_wangsi_cheng",false),
        new Destination("stone_grove","幽冥石林","underworld","stone_grove",false),
        new Destination("dragon_emperor","龙帝栖息区","celestial_dynasty","celestial_plains",true),
        new Destination("eunuch_mastermind","宦官首脑栖息区","celestial_dynasty","celestial_plains",true),
        new Destination("undead_first_emperor","不死始皇栖息区","underworld","underworld_wastes",true),
        new Destination("rebel_general","叛将的幽冥栖息区","underworld","underworld_wastes",true),
        new Destination("nine_heaven_general","九霄天将栖息区","jiuxiao","jiuxiao_skyland",true),
        new Destination("dragon_king","东海龙王栖息区","dragon_palace","dragon_palace_hall",true));

    @SubscribeEvent public static void register(RegisterCommandsEvent e) {
        e.getDispatcher().register(Commands.literal("dynasty_find")
            .executes(c->menu(c.getSource()))
            .then(Commands.argument("destination",StringArgumentType.word())
                .suggests((c,b)->{DESTINATIONS.forEach(d->b.suggest(d.id));return b.buildFuture();})
                .executes(c->search(c.getSource(),StringArgumentType.getString(c,"destination")))));
    }
    private static int menu(CommandSourceStack source) throws com.mojang.brigadier.exceptions.CommandSyntaxException {
        var player=source.getPlayerOrException();
        player.sendSystemMessage(Component.literal("王朝导航：手持探险者指南针找建筑，手持自然指南针找 Boss 栖息区。先进入目标维度，再点击："));
        for(var d:DESTINATIONS)player.sendSystemMessage(Component.literal("["+d.label+"] · ").append(dimensionName(d.dimension))
            .withStyle(s->s.withColor(ChatFormatting.AQUA).withUnderlined(true)
                .withClickEvent(new ClickEvent(ClickEvent.Action.RUN_COMMAND,"/dynasty_find "+d.id))));
        return 1;
    }
    private static int search(CommandSourceStack source,String id) throws com.mojang.brigadier.exceptions.CommandSyntaxException {
        var p=source.getPlayerOrException();
        var d=DESTINATIONS.stream().filter(v->v.id.equals(id)).findFirst().orElse(null);
        if(d==null){source.sendFailure(Component.literal("未知王朝目的地；输入 /dynasty_find 查看列表。"));return 0;}
        if(!p.level().dimension().location().equals(dimensionId(d.dimension))) {
            source.sendFailure(Component.literal("请先进入 ").append(dimensionName(d.dimension))
                .append("。罗盘不会跨维度传送或搜索。"));return 0;
        }
        String mod=d.biome?"naturescompass":"explorerscompass";
        if(!ModList.get().isLoaded(mod)){source.sendFailure(Component.literal("未安装 "+mod+"，王朝本体仍可正常使用。"));return 0;}
        ItemStack stack=p.getMainHandItem();
        if(!new ResourceLocation(mod,mod).equals(ForgeRegistries.ITEMS.getKey(stack.getItem()))) {
            source.sendFailure(Component.literal("请在主手拿着"+(d.biome?"自然指南针":"探险者指南针")+"再点击。"));return 0;
        }
        long now=p.serverLevel().getGameTime();
        var data=p.getPersistentData();
        if(data.contains("DynastyCompassNext")&&now<data.getLong("DynastyCompassNext")
                &&data.getLong("DynastyCompassNext")-now<=100) {
            source.sendFailure(Component.literal("请稍等，导航请求间隔为 5 秒。"));return 0;
        }
        try {
            Object compass=stack.getItem();Class<?> type=compass.getClass();
            if((boolean)type.getMethod("isBroken",ItemStack.class).invoke(compass,stack)) {
                source.sendFailure(Component.literal("罗盘已损坏，请修复或更换。"));return 0;
            }
            var target=new ResourceLocation("dynasty",d.target);
            // Respect the compass owner's blacklist and XP rules instead of bypassing its GUI checks.
            Class<?> utility=Class.forName("com.chaosthedude."+mod+".util."+(d.biome?"BiomeUtils":"StructureUtils"));
            List<?> allowed=(List<?>)(d.biome
                ?utility.getMethod("getAllowedBiomeKeys",net.minecraft.world.level.Level.class).invoke(null,p.serverLevel())
                :utility.getMethod("getAllowedStructureKeys",ServerLevel.class).invoke(null,p.serverLevel()));
            if(!allowed.contains(target)){source.sendFailure(Component.literal("当前罗盘配置不允许搜索这个目标。"));return 0;}
            int cost=(int)(d.biome
                ?utility.getMethod("getXpLevelsForBiome",ResourceLocation.class).invoke(null,target)
                :utility.getMethod("getXpLevelsForStructure",ServerLevel.class,ResourceLocation.class).invoke(null,p.serverLevel(),target));
            if(!p.getAbilities().instabuild&&p.experienceLevel<cost) {
                source.sendFailure(Component.literal("本次搜索需要 "+cost+" 级经验。"));return 0;
            }
            if(d.biome)type.getMethod("searchForBiome",ServerLevel.class,Player.class,ResourceLocation.class,BlockPos.class,ItemStack.class)
                .invoke(compass,p.serverLevel(),p,target,p.blockPosition(),stack);
            else type.getMethod("searchForStructure",ServerLevel.class,Player.class,BlockPos.class,ResourceLocation.class,boolean.class,ItemStack.class)
                .invoke(compass,p.serverLevel(),p,p.blockPosition(),target,false,stack);
            data.putLong("DynastyCompassNext",now+100);
            p.sendSystemMessage(Component.literal(d.biome
                ?"已请求寻找栖息生物群系，不是追踪 Boss 实体；到达后仍需探索。已有信物可用法阵·祭坛召唤复战。"
                :"已请求寻找建筑，搜索结果和距离以罗盘界面为准。"));
            return 1;
        } catch(ReflectiveOperationException | LinkageError ex) {
            Dynasty.LOGGER.warn("Compass integration failed for {}",mod,ex);
            source.sendFailure(Component.literal("当前罗盘版本接口不兼容，请直接右键罗盘手动搜索。"));return 0;
        }
    }

    /** 目的地维度：没有命名空间就默认 dynasty（兼容既有条目）；主世界等原版维度写全名。*/
    private static ResourceLocation dimensionId(String dimension) {
        return dimension.contains(":") ? new ResourceLocation(dimension) : new ResourceLocation("dynasty", dimension);
    }

    private static Component dimensionName(String dimension) {
        var id=dimensionId(dimension);
        // These bilingual dimension keys are maintained by the navigation language generator.
        return Component.translatable("dimension."+id.getNamespace()+"."+id.getPath().replace('/', '.'));
    }
}

package com.dynasty.navigation;

import net.minecraft.resources.ResourceLocation;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResultHolder;
import net.minecraft.world.item.*;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.Level;
import net.minecraftforge.registries.*;
import net.minecraftforge.network.*;
import net.minecraftforge.network.simple.SimpleChannel;
import net.minecraftforge.fml.event.lifecycle.FMLCommonSetupEvent;
import net.minecraftforge.eventbus.api.IEventBus;

public final class CreatureCompass extends Item {
    public static final DeferredRegister<Item> ITEMS=DeferredRegister.create(ForgeRegistries.ITEMS,"dynasty");
    public static final RegistryObject<Item> ITEM=ITEMS.register("creature_compass",()->new CreatureCompass());
    private static final SimpleChannel NET=NetworkRegistry.newSimpleChannel(new ResourceLocation("dynasty","creature_compass"),()->"1","1"::equals,"1"::equals);
    public CreatureCompass(){super(new Item.Properties().stacksTo(1));}
    public static void register(IEventBus bus){ITEMS.register(bus);bus.addListener(CreatureCompass::setup);}
    private static void setup(FMLCommonSetupEvent e){
        NET.registerMessage(0,Request.class,(m,b)->b.writeResourceLocation(m.id),b->new Request(b.readResourceLocation()),(m,c)->{
            var ctx=c.get();ctx.enqueueWork(()->search(ctx.getSender(),m.id));ctx.setPacketHandled(true);
        },java.util.Optional.of(NetworkDirection.PLAY_TO_SERVER));
    }
    public record Request(ResourceLocation id){}
    public static void request(ResourceLocation id){NET.sendToServer(new Request(id));}
    @Override public InteractionResultHolder<ItemStack> use(Level l,Player p,InteractionHand h){
        if(l.isClientSide)net.minecraftforge.fml.DistExecutor.unsafeRunWhenOn(net.minecraftforge.api.distmarker.Dist.CLIENT,()->()->CreatureCompassScreen.open());
        return InteractionResultHolder.sidedSuccess(p.getItemInHand(h),l.isClientSide);
    }
    static void search(net.minecraft.server.level.ServerPlayer p,ResourceLocation id){
        if(p==null)return;ItemStack compass=p.getMainHandItem().is(ITEM.get())?p.getMainHandItem():p.getOffhandItem();
        if(!compass.is(ITEM.get())||p.getCooldowns().isOnCooldown(ITEM.get()))return;
        p.getCooldowns().addCooldown(ITEM.get(),40);
        var type=ForgeRegistries.ENTITY_TYPES.getValue(id);if(type==null)return;
        net.minecraft.world.entity.LivingEntity nearest=null;double distance=256*256;
        for(var entity:p.serverLevel().getAllEntities())if(entity.getType()==type&&entity instanceof net.minecraft.world.entity.LivingEntity living&&living.isAlive()&&!living.isRemoved()){
            double d=p.distanceToSqr(entity);if(d<distance){nearest=living;distance=d;}
        }
        var tag=compass.getOrCreateTag();tag.remove("TargetPos");tag.remove("TargetUuid");tag.putString("TargetName",id.toString());
        if(nearest!=null){tag.putUUID("TargetUuid",nearest.getUUID());tag.putLong("TargetPos",nearest.blockPosition().asLong());tag.putString("TargetDimension",p.level().dimension().location().toString());
            p.sendSystemMessage(Component.translatable(type.getDescriptionId()).append("："+nearest.getBlockX()+", "+nearest.getBlockY()+", "+nearest.getBlockZ()+"（"+(int)Math.sqrt(distance)+"格）"));
        }else p.sendSystemMessage(Component.literal("附近256格已加载区域未发现").append(Component.translatable(type.getDescriptionId())).append("；移动到其栖息地后重新搜索。"));
    }
    @Override public void inventoryTick(ItemStack s,Level level,net.minecraft.world.entity.Entity holder,int slot,boolean selected){
        if(level.isClientSide || level.getGameTime()%20!=0 || !s.hasTag() || !s.getTag().hasUUID("TargetUuid"))return;
